import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updateCustomerGroupsWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updateCustomerGroupsWorkflow(req.scope)
    .run({
      input: {
        selector: {
          id: "cusgrp_123"
        },
        update: {
          name: "VIP"
        }
      }
    })

  res.send(result)
}

